--   q_mtf_prescription_opioids_dvla_001            (MTF, Medicolegal) -- knowledge box "Legal Implications of Driving on Prescription Opioids" + relevantReading (3x)
--   q_emq_imaging_modalities_001                   (EMQ, Physics & Clinical Measurement) -- reference box "Imaging Modalities 1" + relevantReading
--   q_sba_suicide_risk_chronic_pain_001            (SBA, Psychology)  -- knowledge box "Suicide and Chronic Pain" + risk-factor circles image + relevantReading
