insert into questions (id, type, data, status) values ('q_sba_drug_driving_specified_limit_opioid_001', 'SBA', '{"dateAdded":"2026-09-16","rotationIndex":104,"question":"Which of the following opioids has a specified legal limit under the Drug Driving (Specified Limits) Regulations 2015?","choices":["Oxycodone","Fentanyl","Tramadol","Morphine","Codeine"],"correct":3,"explanation":"<p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">The 2015 regulations created a new offence of driving with specified controlled drugs above defined blood concentration limits, covering two groups: illicit drugs with very low (&ldquo;zero tolerance&rdquo;) limits, and a smaller group of commonly prescribed medicines with higher limits reflecting therapeutic use. Among opioids, only morphine (80&nbsp;&micro;g/L), methadone (500&nbsp;&micro;g/L), and 6-monoacetylmorphine (5&nbsp;&micro;g/L &mdash; a heroin-specific marker) are named on the specified list.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>A. Incorrect.</strong> Oxycodone is not included among the specified drugs, despite being widely prescribed and having driving-relevant sedative effects; oxycodone use can still fall under the separate, older &ldquo;impairment&rdquo; offence, but carries no specific blood limit.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>B. Incorrect.</strong> Fentanyl is also not on the specified list, despite being a potent opioid with clear driving-impairment potential.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>C. Incorrect.</strong> Tramadol is not included among the specified drugs, despite common prescription and known sedative/psychomotor effects.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>D. Correct.</strong> Morphine has a specified legal limit of 80&nbsp;&micro;g/L under the regulations &mdash; relevant both to patients prescribed morphine and to heroin users, since heroin is rapidly metabolised to morphine.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>E. Incorrect.</strong> Codeine is not itself listed with a specified limit, though it is metabolised in part to morphine, so heavy or high-dose codeine use could theoretically contribute to a positive morphine result.</p><div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">UK Drug Driving Legislation 2015</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">The Drug Driving (Specified Limits) (England and Wales) Regulations 2015, introduced under section 5A of the Road Traffic Act 1988 and in force from 2 March 2015, created a new offence of driving, attempting to drive, or being in charge of a vehicle with a specified controlled drug above a specified blood concentration limit. This operates alongside &mdash; not instead of &mdash; the pre-existing offence of driving while impaired by drugs, for which no medical defence exists and which applies to any drug, specified or not.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Two Categories of Specified Drug</div><table style=\"margin:0\"><tr><th>Group</th><th>Examples &amp; Limits</th></tr><tr><td>&ldquo;Zero tolerance&rdquo; (illicit/commonly abused)</td><td>Cannabis (THC) 2&nbsp;&micro;g/L; cocaine 10&nbsp;&micro;g/L; ketamine 20&nbsp;&micro;g/L; LSD 1&nbsp;&micro;g/L; MDMA 10&nbsp;&micro;g/L; benzoylecgonine 50&nbsp;&micro;g/L; 6-monoacetylmorphine 5&nbsp;&micro;g/L</td></tr><tr><td>&ldquo;Medicinal&rdquo; (legitimate prescribing use)</td><td>Diazepam 550&nbsp;&micro;g/L; clonazepam 50&nbsp;&micro;g/L; lorazepam 100&nbsp;&micro;g/L; oxazepam 300&nbsp;&micro;g/L; temazepam 1000&nbsp;&micro;g/L; flunitrazepam 300&nbsp;&micro;g/L; methadone 500&nbsp;&micro;g/L; morphine 80&nbsp;&micro;g/L</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Opioids Named With a Specified Limit</div><table style=\"margin:0\"><tr><th>Opioid</th><th>Limit</th><th>Note</th></tr><tr><td>Morphine</td><td>80&nbsp;&micro;g/L</td><td>Relevant to both prescribed use and heroin metabolism</td></tr><tr><td>Methadone</td><td>500&nbsp;&micro;g/L</td><td>Opioid substitution therapy</td></tr><tr><td>6-Monoacetylmorphine</td><td>5&nbsp;&micro;g/L</td><td>Heroin-specific active metabolite, in the zero-tolerance group</td></tr></table><p style=\"margin:10px 0 0;font-size:12.5px;font-style:italic;color:var(--stone)\">Oxycodone, fentanyl, tramadol, and codeine are NOT on the specified list, despite being commonly prescribed opioids with driving-relevant effects &mdash; a frequently tested distinction.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Statutory Medical Defence</div><table style=\"margin:0\"><tr><th>Condition</th><th>Detail</th></tr><tr><td>Applies when</td><td>The drug was prescribed for medical purposes, taken as directed/per the patient information leaflet, and driving was not impaired</td></tr><tr><td>Does not apply when</td><td>Dosing advice was ignored, or driving was in fact impaired &mdash; impairment overrides any medical defence</td></tr><tr><td>Practical point</td><td>Patients on higher doses are encouraged to carry evidence of their prescription (e.g. a repeat prescription slip) when driving</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Penalties for Conviction</div><table style=\"margin:0\"><tr><th>Penalty</th><th>Detail</th></tr><tr><td>Driving ban</td><td>Minimum 1 year</td></tr><tr><td>Fine</td><td>Unlimited</td></tr><tr><td>Imprisonment</td><td>Up to 6 months</td></tr><tr><td>Criminal record</td><td>Remains on the licence for 11 years</td></tr><tr><td>Other</td><td>Significantly increased insurance costs; potential travel restrictions (e.g. visa disclosure of convictions)</td></tr></table></div></div>\n</div></div>","relevantReading":[{"label":"Opioids and Driving","source":"Faculty of Pain Medicine","url":"https://fpm.ac.uk/opioids-and-driving"},{"label":"Changes to Drug Driving Laws","source":"UK Government","url":"https://www.gov.uk/government/collections/drug-driving"}]}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_mtf_drug_driving_medical_defence_001', 'MTF', '{"dateAdded":"2026-09-16","rotationIndex":105,"stem":"Regarding the Drug Driving (Specified Limits) (England and Wales) Regulations 2015:","choices":["Morphine has a very low legal limit","Diazepam has a specified legal limit","Fentanyl has a specified legal limit","A statutory medical defence exists for patients taking a specified drug as prescribed","The medical defence applies if the patient''s driving is impaired"],"correct":[false,true,false,true,false],"explanation":"<p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">The 2015 regulations set two very different tiers of blood concentration limit depending on whether a drug is predominantly illicit or has legitimate medicinal use, and provide a statutory medical defence that protects compliant, non-impaired patients &mdash; but only against the specified-limit offence, never against the separate offence of impaired driving.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>A. FALSE</strong> &mdash; Morphine sits in the &ldquo;medicinal&rdquo; group of specified drugs, which have limits set above the normal therapeutic range (80&nbsp;&micro;g/L) rather than a very low limit. This contrasts with the &ldquo;zero tolerance&rdquo; group of predominantly illicit drugs (e.g. cannabis 2&nbsp;&micro;g/L, cocaine 10&nbsp;&micro;g/L, LSD 1&nbsp;&micro;g/L), which do have very low limits designed to catch any use at all.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>B. TRUE</strong> &mdash; Diazepam has a specified legal limit of 550&nbsp;&micro;g/L, one of the benzodiazepines included in the &ldquo;medicinal&rdquo; group, with the limit set above the normal therapeutic range to protect patients taking it as prescribed.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>C. FALSE</strong> &mdash; Fentanyl is not included among the specified drugs under this legislation, despite being a potent opioid with clear driving-impairment potential; it can still fall under the separate, older &ldquo;impairment&rdquo; offence, but carries no specific blood limit.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>D. TRUE</strong> &mdash; A statutory medical defence exists for patients who were prescribed a specified drug for medical purposes, took it as directed/per the patient information leaflet, and whose driving was not impaired as a result.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>E. FALSE</strong> &mdash; The medical defence does not apply if the patient&rsquo;s driving was impaired &mdash; impairment overrides any medical defence, since no one should be driving while impaired regardless of their medication or prescription status. The defence only protects against the specified-limit offence for patients taking their medication correctly and driving safely.</p><div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">UK Drug Driving Legislation 2015</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">The Drug Driving (Specified Limits) (England and Wales) Regulations 2015, introduced under section 5A of the Road Traffic Act 1988 and in force from 2 March 2015, created a new offence of driving, attempting to drive, or being in charge of a vehicle with a specified controlled drug above a specified blood concentration limit. This operates alongside &mdash; not instead of &mdash; the pre-existing offence of driving while impaired by drugs, for which no medical defence exists and which applies to any drug, specified or not.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Two Categories of Specified Drug</div><table style=\"margin:0\"><tr><th>Group</th><th>Examples &amp; Limits</th></tr><tr><td>&ldquo;Zero tolerance&rdquo; (illicit/commonly abused)</td><td>Cannabis (THC) 2&nbsp;&micro;g/L; cocaine 10&nbsp;&micro;g/L; ketamine 20&nbsp;&micro;g/L; LSD 1&nbsp;&micro;g/L; MDMA 10&nbsp;&micro;g/L; benzoylecgonine 50&nbsp;&micro;g/L; 6-monoacetylmorphine 5&nbsp;&micro;g/L</td></tr><tr><td>&ldquo;Medicinal&rdquo; (legitimate prescribing use)</td><td>Diazepam 550&nbsp;&micro;g/L; clonazepam 50&nbsp;&micro;g/L; lorazepam 100&nbsp;&micro;g/L; oxazepam 300&nbsp;&micro;g/L; temazepam 1000&nbsp;&micro;g/L; flunitrazepam 300&nbsp;&micro;g/L; methadone 500&nbsp;&micro;g/L; morphine 80&nbsp;&micro;g/L</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Opioids Named With a Specified Limit</div><table style=\"margin:0\"><tr><th>Opioid</th><th>Limit</th><th>Note</th></tr><tr><td>Morphine</td><td>80&nbsp;&micro;g/L</td><td>Relevant to both prescribed use and heroin metabolism</td></tr><tr><td>Methadone</td><td>500&nbsp;&micro;g/L</td><td>Opioid substitution therapy</td></tr><tr><td>6-Monoacetylmorphine</td><td>5&nbsp;&micro;g/L</td><td>Heroin-specific active metabolite, in the zero-tolerance group</td></tr></table><p style=\"margin:10px 0 0;font-size:12.5px;font-style:italic;color:var(--stone)\">Oxycodone, fentanyl, tramadol, and codeine are NOT on the specified list, despite being commonly prescribed opioids with driving-relevant effects &mdash; a frequently tested distinction.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Statutory Medical Defence</div><table style=\"margin:0\"><tr><th>Condition</th><th>Detail</th></tr><tr><td>Applies when</td><td>The drug was prescribed for medical purposes, taken as directed/per the patient information leaflet, and driving was not impaired</td></tr><tr><td>Does not apply when</td><td>Dosing advice was ignored, or driving was in fact impaired &mdash; impairment overrides any medical defence</td></tr><tr><td>Practical point</td><td>Patients on higher doses are encouraged to carry evidence of their prescription (e.g. a repeat prescription slip) when driving</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Penalties for Conviction</div><table style=\"margin:0\"><tr><th>Penalty</th><th>Detail</th></tr><tr><td>Driving ban</td><td>Minimum 1 year</td></tr><tr><td>Fine</td><td>Unlimited</td></tr><tr><td>Imprisonment</td><td>Up to 6 months</td></tr><tr><td>Criminal record</td><td>Remains on the licence for 11 years</td></tr><tr><td>Other</td><td>Significantly increased insurance costs; potential travel restrictions (e.g. visa disclosure of convictions)</td></tr></table></div></div>\n</div></div>","relevantReading":[{"label":"Opioids and Driving","source":"Faculty of Pain Medicine","url":"https://fpm.ac.uk/opioids-and-driving"},{"label":"Changes to Drug Driving Laws","source":"UK Government","url":"https://www.gov.uk/government/collections/drug-driving"}]}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_sba_opioid_driving_impairment_hgv_001', 'SBA', '{"dateAdded":"2026-09-16","rotationIndex":106,"question":"A 54-year-old HGV driver with chronic back pain is established on modified-release morphine 50mg twice daily for pain control, with immediate-release morphine used for breakthrough pain. On days when his pain is severe, he can take an additional 20mg of immediate-release morphine four or five times in a day. He sometimes takes zopiclone at night and occasionally has a glass of wine in the evening. He asks whether he can continue driving. What is the most appropriate advice?","choices":["He can drive a regular vehicle but not an HGV","He should be advised that his level of impairment could be comparable to someone above the legal alcohol limit for driving","He should stop driving, as high-dose opioid therapy could risk impairment to judgement","He only needs to avoid driving on days he also takes zopiclone","He can drive as normal provided he carries evidence of his prescription with him"],"correct":1,"explanation":"<p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">On his worst days, this patient&rsquo;s total morphine intake can reach a clinically significant level: his background modified-release dose of 100mg/24 hours, plus up to four or five breakthrough doses of 10&ndash;20mg immediate-release morphine, can add a further 40&ndash;100mg/24 hours &mdash; bringing his total daily morphine intake up to (or above) approximately 200mg/24 hours on severe-pain days. This dose range can be associated with impairment comparable to being above the legal alcohol limit for driving, a risk further compounded by his concurrent zopiclone and occasional alcohol use, both recognised to lower the opioid dose threshold at which impairment occurs.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>A. Incorrect.</strong> Both Group 1 (car/motorcycle) and Group 2 (bus/lorry) licence holders do not require disclosure of a chronic pain condition or the use of appropriately prescribed opioids where there is no evidence of substance misuse or dependence. The relevant offence relates to impairment from use, and the law does not distinguish between illicit and prescribed drugs in this respect.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>B. Correct.</strong> Given his variable but potentially high total daily morphine intake on severe-pain days, combined with concurrent sedative (zopiclone) and occasional alcohol use, he should be counselled that his impairment could be comparable to someone driving above the legal alcohol limit, particularly on days of higher breakthrough use.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>C. Incorrect.</strong> Disproportionate as a blanket statement; advice should focus on risk awareness and appropriate caution on high-use days, rather than automatic, permanent cessation of driving.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>D. Incorrect.</strong> Incomplete &mdash; this fails to address the more significant, dose-dependent impairment risk driven by his variable and potentially high-dose breakthrough morphine use on severe-pain days, which is relevant independently of zopiclone use.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>E. Incorrect.</strong> Prescription evidence only supports a statutory medical defence against the specified legal blood-limit offence if stopped by police; it does not address the separate, more clinically important question of whether he is actually impaired and safe to drive.</p><div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">DVLA and Opioids</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Prescribed opioid use and DVLA notification are governed by a stepwise responsibility framework: the duty to notify sits primarily with the patient, and only shifts toward the prescriber in specific, escalating circumstances.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Do Patients Need to Inform the DVLA?</div><table style=\"margin:0\"><tr><th>Situation</th><th>Notification Needed?</th></tr><tr><td>Group 1 (car/motorcycle), opioids taken as prescribed, not impaired</td><td>No &mdash; even for strong opioids such as morphine, oxycodone, fentanyl, and methadone</td></tr><tr><td>Group 2 (HGV/bus/PCV), opioids taken as prescribed, not impaired</td><td>No, on the same basis, though held to stricter overall medical standards</td></tr><tr><td>Either group, with persistent misuse or dependence</td><td>Yes &mdash; must stop driving and notify the DVLA</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Whose Responsibility, and When It Shifts</div><table style=\"margin:0\"><tr><th>Step</th><th>Action</th></tr><tr><td>1</td><td>Doctor ensures the patient understands their medication may affect driving ability, explains the legal duty to notify the DVLA where relevant, and documents that this advice was given</td></tr><tr><td>2</td><td>If the doctor believes the patient is unfit to drive and has reasonable grounds to think they are continuing anyway, the doctor should make every reasonable effort to persuade them to stop &mdash; potentially involving the patient&rsquo;s next of kin</td></tr><tr><td>3</td><td>If persuasion fails and genuine ongoing concern remains, the doctor may disclose relevant medical information, in confidence, to the DVLA&rsquo;s medical adviser &mdash; without the patient&rsquo;s consent, as a last resort</td></tr><tr><td>4</td><td>Before disclosing, the doctor should inform the patient of the decision wherever practically possible, even though consent is not required at this stage</td></tr></table><p style=\"margin:10px 0 0;font-size:12.5px;font-style:italic;color:var(--stone)\">Per GMC guidance, confidentiality is not absolute &mdash; disclosure without consent is justified specifically where necessary to protect the patient or the wider public from a risk of death or serious harm.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">When Driving Advice Specifically Applies</div><table style=\"margin:0\"><tr><th>Point</th><th>Detail</th></tr><tr><td>Starting therapy or dose change</td><td>Advise not to drive for at least a few days (commonly ~5 days) until effects have stabilised</td></tr><tr><td>Warning symptoms</td><td>Should not drive if feeling drowsy, dizzy, unable to concentrate, or with blurred vision</td></tr><tr><td>Concurrent sedatives/alcohol</td><td>Significantly increases risk and should prompt extra caution</td></tr><tr><td>Timing</td><td>Discussed at initiation of opioid therapy and at each dose change</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Documentation</div><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Discussions about driving and opioid medication should be clearly documented in the medical notes, with written information (e.g. a patient information leaflet) also given to the patient. This protects both the patient (supporting the statutory medical defence if needed) and the prescriber (evidencing that appropriate advice was given).</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Key Distinction: Legal Limit vs Fitness to Drive</div><table style=\"margin:0\"><tr><th>Concept</th><th>Detail</th></tr><tr><td>Specified-limit offence</td><td>Relates to the separate statutory offence under the 2015 regulations &mdash; exceeding a named drug&rsquo;s blood concentration, e.g. morphine 80&nbsp;&micro;g/L</td></tr><tr><td>Fitness to drive</td><td>A patient can be legally compliant (below the limit, or protected by the medical defence) and still be clinically unfit/impaired to drive, and vice versa</td></tr><tr><td>Ultimate responsibility</td><td>Day-to-day assessment of personal fitness to drive rests with the individual driver; the healthcare provider&rsquo;s duty escalates only if the patient demonstrably fails to meet that responsibility despite being properly informed</td></tr></table></div></div>\n</div></div>","relevantReading":[{"label":"Assessing Fitness to Drive: A Guide for Medical Professionals","source":"DVLA","url":"https://assets.publishing.service.gov.uk/media/690c6d0a68fffdd77951aab0/assessing-fitness-to-drive-november-2025.pdf"},{"label":"Opioids and Driving","source":"Faculty of Pain Medicine","url":"https://fpm.ac.uk/opioids-and-driving"},{"label":"Changes to Drug Driving Laws","source":"UK Government","url":"https://www.gov.uk/government/collections/drug-driving"}]}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_sba_morphine_driving_prosecution_001', 'SBA', '{"dateAdded":"2026-09-16","rotationIndex":107,"question":"A 60-year-old woman is started on modified-release morphine for chronic back pain. She asks about the legal implications for driving. What is the most accurate information to give her?","choices":["She must inform the DVLA before starting the medication","She is committing an offence if her blood morphine level exceeds the specified legal limit, regardless of whether she is impaired","She can be prosecuted for driving with morphine in her blood above the specified legal limit, even if taken as prescribed and not impaired","She will automatically lose her licence once started on strong opioids","She only needs to worry about the law if she is also drinking alcohol"],"correct":2,"explanation":"<p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">The Drug Driving (Specified Limits) (England and Wales) Regulations 2015 created an offence of driving with specified drugs, including morphine, above a defined blood concentration limit &mdash; a limits-based offence, separate from the pre-existing offence of driving while impaired. The specified limit allows for the normal recommended doses that most patients would be prescribed, but patients on higher-dose opioid therapy could still be found to be above the limit, risking an intention to prosecute. A statutory medical defence exists to protect such patients, but it must be actively relied upon if the patient is tested and found to be over the limit.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>A. Incorrect.</strong> Patients on both Group 1 and Group 2 licences taking prescribed opioids as directed generally do not need to routinely notify the DVLA. They should stop driving and inform the DVLA only if there is substance misuse or dependence.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>B. Incorrect.</strong> Overly simplistic &mdash; while there may be an intention to prosecute if found driving above the specified limit, this does not translate to automatic commission of an offence if the statutory medical defence is used to show the drug was taken appropriately as prescribed, without impairment.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>C. Correct.</strong> This accurately reflects the legal framework: prosecution is based on exceeding the specified blood limit itself, irrespective of impairment, but a statutory medical defence protects patients who were prescribed the drug, took it as directed, and were not impaired at the time.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>D. Incorrect.</strong> Starting strong opioid therapy does not automatically result in licence loss; ongoing fitness to drive depends on individual response, dose, and whether driving is actually impaired.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>E. Incorrect.</strong> While alcohol and other sedatives compound risk and lower the impairment threshold, the specified-limit offence and the general impairment offence both apply to opioid use in isolation, regardless of concurrent alcohol intake.</p><div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">UK Drug Driving Legislation 2015</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">The Drug Driving (Specified Limits) (England and Wales) Regulations 2015, introduced under section 5A of the Road Traffic Act 1988 and in force from 2 March 2015, created a new offence of driving, attempting to drive, or being in charge of a vehicle with a specified controlled drug above a specified blood concentration limit. This operates alongside &mdash; not instead of &mdash; the pre-existing offence of driving while impaired by drugs, for which no medical defence exists and which applies to any drug, specified or not.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Two Categories of Specified Drug</div><table style=\"margin:0\"><tr><th>Group</th><th>Examples &amp; Limits</th></tr><tr><td>&ldquo;Zero tolerance&rdquo; (illicit/commonly abused)</td><td>Cannabis (THC) 2&nbsp;&micro;g/L; cocaine 10&nbsp;&micro;g/L; ketamine 20&nbsp;&micro;g/L; LSD 1&nbsp;&micro;g/L; MDMA 10&nbsp;&micro;g/L; benzoylecgonine 50&nbsp;&micro;g/L; 6-monoacetylmorphine 5&nbsp;&micro;g/L</td></tr><tr><td>&ldquo;Medicinal&rdquo; (legitimate prescribing use)</td><td>Diazepam 550&nbsp;&micro;g/L; clonazepam 50&nbsp;&micro;g/L; lorazepam 100&nbsp;&micro;g/L; oxazepam 300&nbsp;&micro;g/L; temazepam 1000&nbsp;&micro;g/L; flunitrazepam 300&nbsp;&micro;g/L; methadone 500&nbsp;&micro;g/L; morphine 80&nbsp;&micro;g/L</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Opioids Named With a Specified Limit</div><table style=\"margin:0\"><tr><th>Opioid</th><th>Limit</th><th>Note</th></tr><tr><td>Morphine</td><td>80&nbsp;&micro;g/L</td><td>Relevant to both prescribed use and heroin metabolism</td></tr><tr><td>Methadone</td><td>500&nbsp;&micro;g/L</td><td>Opioid substitution therapy</td></tr><tr><td>6-Monoacetylmorphine</td><td>5&nbsp;&micro;g/L</td><td>Heroin-specific active metabolite, in the zero-tolerance group</td></tr></table><p style=\"margin:10px 0 0;font-size:12.5px;font-style:italic;color:var(--stone)\">Oxycodone, fentanyl, tramadol, and codeine are NOT on the specified list, despite being commonly prescribed opioids with driving-relevant effects &mdash; a frequently tested distinction.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Statutory Medical Defence</div><table style=\"margin:0\"><tr><th>Condition</th><th>Detail</th></tr><tr><td>Applies when</td><td>The drug was prescribed for medical purposes, taken as directed/per the patient information leaflet, and driving was not impaired</td></tr><tr><td>Does not apply when</td><td>Dosing advice was ignored, or driving was in fact impaired &mdash; impairment overrides any medical defence</td></tr><tr><td>Practical point</td><td>Patients on higher doses are encouraged to carry evidence of their prescription (e.g. a repeat prescription slip) when driving</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Penalties for Conviction</div><table style=\"margin:0\"><tr><th>Penalty</th><th>Detail</th></tr><tr><td>Driving ban</td><td>Minimum 1 year</td></tr><tr><td>Fine</td><td>Unlimited</td></tr><tr><td>Imprisonment</td><td>Up to 6 months</td></tr><tr><td>Criminal record</td><td>Remains on the licence for 11 years</td></tr><tr><td>Other</td><td>Significantly increased insurance costs; potential travel restrictions (e.g. visa disclosure of convictions)</td></tr></table></div></div>\n</div></div>","relevantReading":[{"label":"Opioids and Driving","source":"Faculty of Pain Medicine","url":"https://fpm.ac.uk/opioids-and-driving"},{"label":"Changes to Drug Driving Laws","source":"UK Government","url":"https://www.gov.uk/government/collections/drug-driving"}]}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_mtf_prescription_opioids_dvla_001', 'MTF', '{"dateAdded":"2026-09-16","rotationIndex":108,"stem":"Regarding prescription opioids in the UK:","choices":["A patient can be prosecuted for driving with morphine above the specified legal limit even if not clinically impaired","The statutory medical defence protects a patient from prosecution for impaired driving, provided the drug was taken as prescribed","Group 1 licence holders must notify the DVLA when starting regular opioid therapy","Group 2 (HGV/bus) licence holders must notify the DVLA when starting regular opioid therapy","A doctor may disclose a patient''s condition to the DVLA without consent if the patient continues to drive against medical advice and poses a risk of serious harm"],"correct":[true,false,false,false,true],"explanation":"<p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">UK law separates a specified-limit blood-concentration offence from the general impairment offence, and neither routine Group 1 nor Group 2 licensing requires notification purely for starting appropriately prescribed opioid therapy &mdash; though a doctor&rsquo;s duty of confidentiality can, exceptionally, give way to disclosure.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>A. TRUE</strong> &mdash; The specified-limit offence under the 2015 regulations is based on exceeding the defined blood concentration of the drug (e.g. morphine at 80&nbsp;&micro;g/L), irrespective of whether the patient is actually clinically impaired. This is why the statutory medical defence exists separately, to protect compliant, non-impaired patients from prosecution under this specific offence.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>B. FALSE</strong> &mdash; The statutory medical defence protects against the specified-limit offence only, for patients who took the drug as prescribed, as directed, and were not impaired. It provides no defence whatsoever against the separate offence of driving while impaired, which applies regardless of prescription status or blood levels.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>C. FALSE</strong> &mdash; Group 1 licence holders do not routinely need to inform the DVLA on starting prescription opioids taken as directed, provided driving is not impaired.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>D. FALSE</strong> &mdash; Group 2 licence holders are held to stricter medical standards overall, but this does not translate into a blanket requirement to routinely notify the DVLA simply for starting regular opioid therapy; a medical assessment already covers current medication when applying for or renewing a Group 2 licence.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>E. TRUE</strong> &mdash; Per GMC guidance, confidentiality is not absolute. If a doctor&rsquo;s efforts to persuade a patient to inform the DVLA and stop driving fail, and the doctor has reasonable grounds to believe the patient continues to drive despite posing a risk of serious harm, the doctor may disclose relevant information to the DVLA&rsquo;s medical adviser without the patient&rsquo;s consent, as a last resort, having ideally informed the patient of this decision beforehand.</p><div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Legal Implications of Driving on Prescription Opioids</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Two separate legal frameworks govern opioid-related driving offences in the UK, and it is a frequently tested distinction that a patient can comply with one while still breaching the other.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Two Separate Legal Frameworks</div><table style=\"margin:0\"><tr><th>Offence</th><th>Basis</th></tr><tr><td>Specified-limit offence (2015 regulations)</td><td>Driving with a named drug (e.g. morphine 80&nbsp;&micro;g/L, methadone 500&nbsp;&micro;g/L) above its specified blood concentration, regardless of impairment</td></tr><tr><td>Impairment offence (Road Traffic Act 1988)</td><td>Driving while actually impaired by any drug, prescribed or otherwise &mdash; no medical defence applies to this offence</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Statutory Medical Defence</div><table style=\"margin:0\"><tr><th>Point</th><th>Detail</th></tr><tr><td>Applies to</td><td>The specified-limit offence only</td></tr><tr><td>Available where</td><td>The patient (i) was prescribed the drug for medical purposes, (ii) took it as directed/per the patient information leaflet, and (iii) was not impaired at the time</td></tr><tr><td>Does not apply if</td><td>Dosing advice was ignored, or the patient was in fact impaired</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">General Legal Duty to Notify the DVLA</div><table style=\"margin:0\"><tr><th>Licence</th><th>Position</th></tr><tr><td>Trigger for notification</td><td>A condition or medication with a likely impact on safe driving ability &mdash; not simply the fact of taking a particular drug class</td></tr><tr><td>Group 1 (car/motorcycle)</td><td>Prescribed opioid use, taken appropriately and not affecting driving, does not itself trigger a notification requirement</td></tr><tr><td>Group 2 (HGV/bus/PCV)</td><td>Subject to stricter overall medical standards, and opioid-based medication is a recognised area of relevance, but notification still depends on individual assessment of impact on safe driving &mdash; not an automatic, routine requirement purely because opioid therapy has started</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Escalation to Healthcare Provider Responsibility</div><table style=\"margin:0\"><tr><th>Step</th><th>Action</th></tr><tr><td>1</td><td>Doctor informs and advises the patient of relevant risks and their legal duty to notify the DVLA where applicable</td></tr><tr><td>2</td><td>If the patient continues driving against advice, the doctor makes reasonable efforts to persuade them to stop, potentially involving next of kin</td></tr><tr><td>3</td><td>If this fails and a risk of serious harm persists, the doctor may notify the DVLA directly, in confidence, without consent &mdash; a last resort, per GMC confidentiality guidance and DVLA guidance stating doctors should notify when an individual &ldquo;cannot or will not&rdquo; do so themselves</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Documentation</div><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">All discussions regarding opioids and driving should be clearly documented in the medical notes, with written information ideally also given to the patient &mdash; both to support the statutory medical defence and to evidence appropriate prescriber advice.</p></div></div>\n</div></div>","relevantReading":[{"label":"Opioids and Driving","source":"Faculty of Pain Medicine","url":"https://fpm.ac.uk/opioids-and-driving"},{"label":"Changes to Drug Driving Laws","source":"UK Government","url":"https://www.gov.uk/government/collections/drug-driving"},{"label":"Assessing Fitness to Drive: A Guide for Medical Professionals","source":"DVLA","url":"https://assets.publishing.service.gov.uk/media/690c6d0a68fffdd77951aab0/assessing-fitness-to-drive-november-2025.pdf"}]}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_emq_imaging_modalities_001', 'EMQ', '{"dateAdded":"2026-09-16","rotationIndex":109,"stem":"Imaging modalities for spinal and pain-related pathology","lead":"For each scenario below, select the single most appropriate imaging technique from the options above. Each option may be used once, more than once, or not at all.","options":["Ultrasound","CT","MRI scan","MRI spectroscopy","MRI with gadolinium contrast","Isotope bone scan","PET scan","DEXA scan"],"questions":[{"question":"Suspected discogenic process/inflammation","correct":4,"explanation":"<strong>E. MRI with gadolinium contrast</strong> &mdash; the investigation of choice for suspected discitis/discogenic inflammation, as contrast enhancement highlights areas of active inflammation, helps distinguish infective/inflammatory change from degenerative disease, and can identify associated epidural abscess formation."},{"question":"Suspected osteoporosis","correct":7,"explanation":"<strong>H. DEXA scan</strong> &mdash; the gold-standard investigation for diagnosing osteoporosis, measuring bone mineral density and generating a T-score to quantify fracture risk."},{"question":"Suspected occult vertebral insufficiency fracture","correct":5,"explanation":"<strong>F. Isotope bone scan</strong> &mdash; highly sensitive for detecting occult vertebral insufficiency/compression fractures not visible on plain X-ray, showing increased tracer uptake at sites of bone turnover/microfracture before structural changes become radiographically apparent."},{"question":"Ultrasound guidance for an obturator nerve block","correct":0,"explanation":"<strong>A. Ultrasound</strong> &mdash; provides real-time, dynamic visualisation of soft tissue, vessels, and nerves without ionising radiation, making it well suited for guiding peripheral nerve blocks."},{"question":"Suspected metastatic disease in a patient with known malignancy","correct":6,"explanation":"<strong>G. PET scan</strong> &mdash; often combined with CT (PET-CT), the investigation of choice for staging suspected metastatic disease, using a radiolabelled glucose analogue (FDG) to identify metabolically active malignant deposits throughout the body."}],"reference":"<div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Imaging Modalities 1</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Choosing the right imaging modality in pain medicine depends on whether the question is anatomical/structural (CT, MRI), functional/metabolic (bone scan, PET, SPECT-CT), or procedural (ultrasound), and on the specific pathology suspected.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Ultrasound</div><table style=\"margin:0\"><tr><th>Property</th><th>Detail</th></tr><tr><td>Mechanism</td><td>High-frequency sound waves generated via the piezoelectric effect</td></tr><tr><td>Strengths</td><td>No ionising radiation &mdash; safe for repeated use, pregnancy, paediatrics; real-time, dynamic visualisation, ideal for guiding interventional procedures (nerve blocks, joint injections, vascular access)</td></tr><tr><td>Limitations</td><td>Limited penetration through bone and gas-containing structures (bowel, lung); operator-dependent</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">CT (Computed Tomography)</div><table style=\"margin:0\"><tr><th>Property</th><th>Detail</th></tr><tr><td>Mechanism</td><td>Rotating X-ray beams and detectors generate cross-sectional images based on differential tissue attenuation</td></tr><tr><td>Strengths</td><td>Excellent bony detail (fractures, degenerative changes, procedure planning); fast acquisition, useful in acute/trauma settings; can be combined with contrast for vascular/soft tissue characterisation</td></tr><tr><td>Limitations</td><td>Involves ionising radiation</td></tr><tr><td>SPECT-CT</td><td>Combines SPECT &mdash; a 3D functional nuclear medicine technique using a gamma-emitting radiotracer, similar in principle to a standard isotope bone scan but tomographic rather than planar &mdash; with a co-registered CT for precise anatomical localisation. Particularly useful for identifying the specific symptomatic level in multi-level spinal degenerative disease (e.g. confirming which facet joint or pars defect is metabolically &ldquo;hot&rdquo;), guiding targeted intervention. Involves a higher combined radiation burden than either technique alone</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">MRI Scan</div><table style=\"margin:0\"><tr><th>Property</th><th>Detail</th></tr><tr><td>Mechanism</td><td>Magnetic behaviour of hydrogen protons in a strong magnetic field, combined with radiofrequency pulses (T1/T2 weighting)</td></tr><tr><td>Strengths</td><td>No ionising radiation; superior soft tissue contrast &mdash; discs, nerve roots, ligaments, spinal cord, muscle; standard modality for suspected disc prolapse, spinal stenosis, nerve root compression</td></tr><tr><td>Limitations</td><td>Contraindicated with certain ferromagnetic implants/devices (non-MRI-conditional pacemakers, some aneurysm clips)</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">MRI Spectroscopy</div><table style=\"margin:0\"><tr><th>Property</th><th>Detail</th></tr><tr><td>Mechanism</td><td>Analyses the biochemical composition of tissue rather than just its anatomical structure, measuring concentrations of specific metabolites (e.g. N-acetylaspartate, choline, lactate)</td></tr><tr><td>Use</td><td>Characterising tissue metabolism &mdash; particularly differentiating tumour recurrence from radiation necrosis, and some neuro-oncological research applications</td></tr><tr><td>Note</td><td>Not part of routine structural spinal imaging; a specialised, less commonly used adjunct technique</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">MRI With Gadolinium Contrast</div><table style=\"margin:0\"><tr><th>Property</th><th>Detail</th></tr><tr><td>Mechanism</td><td>Standard MRI plus IV gadolinium-based contrast, highlighting areas of increased vascularity, blood&ndash;spinal cord barrier breakdown, or active inflammation</td></tr><tr><td>Key uses</td><td>Distinguishing infection/inflammation (e.g. discitis, epidural abscess) from degenerative change; identifying tumour enhancement; differentiating recurrent disc herniation from post-surgical scar tissue (scar enhances, recurrent disc typically does not)</td></tr><tr><td>Caution</td><td>Severe renal impairment (risk of nephrogenic systemic fibrosis)</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Isotope (Radionuclide) Bone Scan</div><table style=\"margin:0\"><tr><th>Property</th><th>Detail</th></tr><tr><td>Mechanism</td><td>A radiolabelled tracer (typically technetium-99m-MDP) is taken up preferentially at sites of increased bone turnover/osteoblastic activity, imaged with a gamma camera</td></tr><tr><td>Strengths</td><td>Highly sensitive (though not specific) for occult fractures, infection, metastatic bone disease, Paget&rsquo;s disease; detects functional/metabolic change often before structural change is visible on X-ray; whole-body imaging, useful for screening multiple lesions</td></tr><tr><td>Note</td><td>Produces planar (2D) images, unlike the tomographic (3D) images of SPECT-CT</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">PET Scan</div><table style=\"margin:0\"><tr><th>Property</th><th>Detail</th></tr><tr><td>Mechanism</td><td>A radiolabelled tracer (typically FDG, a glucose analogue) is taken up preferentially by metabolically active cells; positron emissions are reconstructed into functional images</td></tr><tr><td>Use</td><td>Primarily oncological staging &mdash; identifying primary tumours, metastases, and treatment response; often combined with CT (PET-CT) to overlay functional data onto anatomical images</td></tr><tr><td>Limitations</td><td>Involves ionising radiation exposure</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">DEXA Scan (Dual-Energy X-ray Absorptiometry)</div><table style=\"margin:0\"><tr><th>Property</th><th>Detail</th></tr><tr><td>Mechanism</td><td>Two different X-ray energy beams passed through bone (typically lumbar spine and femoral neck) calculate bone mineral density from differential absorption by bone versus soft tissue</td></tr><tr><td>Use</td><td>The gold-standard investigation for diagnosing osteoporosis; generates a T-score (vs young-adult reference population) and Z-score (vs age-matched population); used for diagnosis, fracture risk assessment, and monitoring treatment response</td></tr><tr><td>Strengths</td><td>Low radiation dose, quick, non-invasive</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Bone Scan vs DEXA Scan &mdash; Key Distinction</div><table style=\"margin:0\"><tr><th>Feature</th><th>Isotope Bone Scan</th><th>DEXA Scan</th></tr><tr><td>What it measures</td><td>Functional bone turnover/metabolic activity (osteoblastic activity)</td><td>Bone mineral density (structural bone mass)</td></tr><tr><td>Purpose</td><td>Detects acute pathology: fractures (including occult), infection, metastases, Paget&rsquo;s disease</td><td>Diagnoses and monitors osteoporosis and fracture risk</td></tr><tr><td>Timing relevance</td><td>Detects acute/recent changes &mdash; positive quickly after an insult, before structural change is visible on X-ray</td><td>Reflects chronic, cumulative bone density status &mdash; does not identify acute lesions or fractures directly</td></tr><tr><td>Clinical use case</td><td>&ldquo;Is there an acute or ongoing bony process happening right now, and where?&rdquo;</td><td>&ldquo;How strong/dense is this patient&rsquo;s bone, and are they at risk of fragility fracture?&rdquo;</td></tr><tr><td>Radiation</td><td>Involves radioactive tracer administration</td><td>Very low-dose X-ray, no radioactive tracer</td></tr></table></div></div>\n</div>","relevantReading":[{"label":"Diagnostic Imaging and Pain Management","source":"AnesKey","url":"https://aneskey.com/diagnostic-imaging-and-pain-management/"}]}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_sba_suicide_risk_chronic_pain_001', 'SBA', '{"dateAdded":"2026-09-16","rotationIndex":110,"question":"A 45-year-old man with chronic widespread pain attends clinic. Which of the following is most strongly associated with increased suicide risk in patients with chronic pain?","choices":["Suicidal thoughts","Female sex","Male sex","History of depression","Low socioeconomic status"],"correct":0,"explanation":"<p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">While all of the listed factors are associated with increased suicide risk, the presence of suicidal thoughts (ideation) itself is the single strongest predictor of subsequent suicidal behaviour or completed suicide &mdash; the most proximal and directly measurable marker of risk, compared with the other, more distal contributing factors listed.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>A. Correct.</strong> The presence of suicidal ideation is the most immediate and strongest predictor of future suicidal behaviour and completed suicide &mdash; a direct marker of risk rather than an indirect contributing factor, making it the most clinically significant &ldquo;red flag&rdquo; requiring urgent assessment and action.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>B. Incorrect.</strong> Female sex is associated with higher rates of suicide attempts, but lower rates of completed suicide compared with males.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>C. Incorrect.</strong> Male sex is associated with higher rates of completed suicide, but this is a less direct and less clinically actionable marker than the presence of active ideation.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>D. Incorrect.</strong> A history of depression is a significant and well-established risk factor for suicidality in chronic pain, and is frequently comorbid with it, but remains a more distal contributor than active suicidal ideation itself.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>E. Incorrect.</strong> Low socioeconomic status is a recognised general risk factor for suicide, acting via associated stressors such as financial strain, reduced access to care, and social disadvantage.</p><div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Suicide and Chronic Pain</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Most patients who attempt or complete suicide have prior suicidal ideation, which is why ideation itself is the single strongest predictor of subsequent suicidal behaviour. Chronic pain is independently associated with increased suicide risk, compounded by a range of pain-related, sociodemographic, personal, and psychological factors &mdash; and offset by identifiable protective factors.</p><div style=\"text-align:center\"><img src=\"images/suicide-risk-circles.svg\" alt=\"Risk and protective factors for suicide in chronic pain: pain-related, sociodemographic, personal background, and psychological risk factors surrounding a central suicide-risk hub, with suicidal ideation highlighted as the strongest single predictor and protective factors shown separately\" style=\"max-width:100%;border-radius:10px;margin-top:12px;border:1px solid #EDE3D7\"></div></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Pain-Related Risk Factors</div><table style=\"margin:0\"><tr><th>Factor</th><th>Detail</th></tr><tr><td>Pain intensity</td><td>Risk of suicidal ideation and attempts increases with pain intensity; moderate-to-severe pain in the year before accessing pain services is independently associated with subsequent suicide attempts</td></tr><tr><td>Type of pain</td><td>Increased risk has been described with most chronic pain conditions; after adjusting for comorbid psychiatric conditions, associations remain clearest for back pain and migraine</td></tr><tr><td>Sleep disturbance</td><td>Present in 50&ndash;80% of chronic pain patients; a bidirectional relationship with pain exists, and severe insomnia with daytime dysfunction is independently associated with suicidal ideation, even after accounting for depression</td></tr><tr><td>Pain catastrophising</td><td>A maladaptive coping style (amplifying the threat value of pain, helplessness, persistence of pain-related thoughts) that is a consistent predictor of suicidal ideation and behaviour, partly mediated by depression</td></tr><tr><td>Opioid use</td><td>Higher prescribed opioid doses are associated with increased suicide risk, even after adjusting for demographic and clinical factors; risk is also increased in the months after stopping opioid treatment, particularly with longer prior treatment duration</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">General Risk Factors</div><table style=\"margin:0\"><tr><th>Category</th><th>Examples</th></tr><tr><td>Sociodemographic</td><td>Stressful life events (job loss, relationship instability); male sex, LGBT+ identity, ethnic minority status; lack of social support</td></tr><tr><td>Personal background</td><td>Substance misuse; closeness to someone who died by suicide or exposure to suicidal behaviour/suicide-promoting media; access to lethal means</td></tr><tr><td>Psychological</td><td>Previous self-harm or suicide attempts; mental illness, especially recent relapse or discharge from inpatient care; impulsivity or personality disorder; disengagement from mental health services; hopelessness, helplessness, guilt, entrapment, shame; psychotic phenomena</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Protective Factors</div><table style=\"margin:0\"><tr><th>Category</th><th>Examples</th></tr><tr><td>Individual</td><td>Problem-solving ability; self-control of thoughts, behaviour, and emotions; hopefulness, reasons for living, optimism</td></tr><tr><td>Psychosocial</td><td>Connectedness to family, community, and social institutions; religious faith and spirituality; employment</td></tr><tr><td>Access</td><td>Easy access to effective clinical and psychological care</td></tr></table></div></div>\n</div></div>","relevantReading":[{"label":"Suicidality in Chronic Pain: Assessment and Management","source":"BJA Education","url":"https://www.bjaed.org/article/S2058-5349(23)00078-1/fulltext"}]}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_mtf_suicide_risk_factors_chronic_pain_001', 'MTF', '{"dateAdded":"2026-09-16","rotationIndex":111,"stem":"Factors associated with increased suicide risk in patients with chronic pain:","choices":["Pain catastrophising","Insomnia","Strong social support network","Depression","Longer duration of chronic pain"],"correct":[true,true,false,true,true],"explanation":"<p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Suicide risk in chronic pain is shaped by an interacting set of pain-related and psychological factors, offset by recognised protective factors such as social connectedness.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>A. TRUE</strong> &mdash; Pain catastrophising, an exaggerated, negative cognitive and emotional orientation towards actual or anticipated pain, is one of the most robust and consistently identified predictors of suicidal ideation and behaviour in chronic pain populations.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>B. TRUE</strong> &mdash; Sleep disturbance/insomnia is independently associated with increased suicide risk, both in the general population and specifically in chronic pain patients, where pain and poor sleep frequently perpetuate one another and compound psychological distress.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>C. FALSE</strong> &mdash; A strong social support network is a recognised protective factor against suicide, not a risk factor. Social isolation and lack of support are the risk factors, with connectedness generally buffering against suicidal ideation and behaviour.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>D. TRUE</strong> &mdash; Comorbid depression is one of the strongest and most consistently identified risk factors for suicidality in chronic pain, with the two conditions frequently co-occurring and interacting to worsen prognosis and increase risk.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>E. TRUE</strong> &mdash; Longer duration and higher intensity of chronic pain are associated with increased suicide risk, reflecting cumulative psychological, social, occupational, and functional burden over time, as well as an increased likelihood of developing secondary depression, hopelessness, and catastrophising.</p><div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Suicide and Chronic Pain</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Most patients who attempt or complete suicide have prior suicidal ideation, which is why ideation itself is the single strongest predictor of subsequent suicidal behaviour. Chronic pain is independently associated with increased suicide risk, compounded by a range of pain-related, sociodemographic, personal, and psychological factors &mdash; and offset by identifiable protective factors.</p><div style=\"text-align:center\"><img src=\"images/suicide-risk-circles.svg\" alt=\"Risk and protective factors for suicide in chronic pain: pain-related, sociodemographic, personal background, and psychological risk factors surrounding a central suicide-risk hub, with suicidal ideation highlighted as the strongest single predictor and protective factors shown separately\" style=\"max-width:100%;border-radius:10px;margin-top:12px;border:1px solid #EDE3D7\"></div></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Pain-Related Risk Factors</div><table style=\"margin:0\"><tr><th>Factor</th><th>Detail</th></tr><tr><td>Pain intensity</td><td>Risk of suicidal ideation and attempts increases with pain intensity; moderate-to-severe pain in the year before accessing pain services is independently associated with subsequent suicide attempts</td></tr><tr><td>Type of pain</td><td>Increased risk has been described with most chronic pain conditions; after adjusting for comorbid psychiatric conditions, associations remain clearest for back pain and migraine</td></tr><tr><td>Sleep disturbance</td><td>Present in 50&ndash;80% of chronic pain patients; a bidirectional relationship with pain exists, and severe insomnia with daytime dysfunction is independently associated with suicidal ideation, even after accounting for depression</td></tr><tr><td>Pain catastrophising</td><td>A maladaptive coping style (amplifying the threat value of pain, helplessness, persistence of pain-related thoughts) that is a consistent predictor of suicidal ideation and behaviour, partly mediated by depression</td></tr><tr><td>Opioid use</td><td>Higher prescribed opioid doses are associated with increased suicide risk, even after adjusting for demographic and clinical factors; risk is also increased in the months after stopping opioid treatment, particularly with longer prior treatment duration</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">General Risk Factors</div><table style=\"margin:0\"><tr><th>Category</th><th>Examples</th></tr><tr><td>Sociodemographic</td><td>Stressful life events (job loss, relationship instability); male sex, LGBT+ identity, ethnic minority status; lack of social support</td></tr><tr><td>Personal background</td><td>Substance misuse; closeness to someone who died by suicide or exposure to suicidal behaviour/suicide-promoting media; access to lethal means</td></tr><tr><td>Psychological</td><td>Previous self-harm or suicide attempts; mental illness, especially recent relapse or discharge from inpatient care; impulsivity or personality disorder; disengagement from mental health services; hopelessness, helplessness, guilt, entrapment, shame; psychotic phenomena</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Protective Factors</div><table style=\"margin:0\"><tr><th>Category</th><th>Examples</th></tr><tr><td>Individual</td><td>Problem-solving ability; self-control of thoughts, behaviour, and emotions; hopefulness, reasons for living, optimism</td></tr><tr><td>Psychosocial</td><td>Connectedness to family, community, and social institutions; religious faith and spirituality; employment</td></tr><tr><td>Access</td><td>Easy access to effective clinical and psychological care</td></tr></table></div></div>\n</div></div>","relevantReading":[{"label":"Suicidality in Chronic Pain: Assessment and Management","source":"BJA Education","url":"https://www.bjaed.org/article/S2058-5349(23)00078-1/fulltext"}]}'::jsonb, 'published')
  on conflict (id) do nothing;

